package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"time"

	demogo "github.com/jepsen-io/maelstrom/demo/go"
)

// The node handles count and total operations using seq-kv as the single source of truth.
func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	node := demogo.NewNode(ctx, "node", "")
	seqKV := demogo.NewSeqKV(node, "g-counter")
	config := node.Config{
		Name:  "node",
		Type:  "g-counter",
		LogTo: os.Stdout,
	}

	node.Run(config)
	node.Handle("init", func(ctx context.Context, msg demogo.Message, reply demogo.ReplyFn) {
		if err := node.Init(); err != nil {
			panic(err)
		}
		reply(OK())
	})

	// Handle count: increment the global counter in seq-kv
	node.Handle("count", func(ctx context.Context, msg demogo.Message, reply demogo.ReplyFn) {
		var req struct {
			Type      string `json:"type"`
			MsgID     int64  `json:"msg_id"`
			Visitors  int    `json:"visitors"`
		}
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			panic(fmt.Sprintf("unmarshal: %v", err))
		}

		currentVal, _ := seqKV.ReadInt(ctx, "total")
		newVal := currentVal + req.Visitors
		if err := seqKV.Write(ctx, "total", fmt.Sprintf("%d", newVal)); err != nil {
			panic(fmt.Sprintf("seq-kv write: %v", err))
		}

		resp := demogo.Response{
			Type:     "counted",
			MsgID:    req.MsgID,
			InReplyTo: msg.ID(),
		}
		if e := reply(OK(resp)); e != nil {
			fmt.Fprintf(os.Stderr, "%v\n", e)
		}
	})

	// Handle total: read the global counter from seq-kv
	node.Handle("total", func(ctx context.Context, msg demogo.Message, reply demogo.ReplyFn) {
		var req struct {
			Type  string `json:"type"`
			MsgID int64  `json:"msg_id"`
		}
		if err := json.Unmarshal(msg.Body, &req); err != nil {
			panic(fmt.Sprintf("unmarshal: %v", err))
		}

		val, _ := seqKV.ReadInt(ctx, "total")
		resp := demogo.Response{
			Type:        "total_is",
			MsgID:       req.MsgID,
			InReplyTo:   msg.ID(),
			VisitorsSoFar: val,
		}
		if e := reply(OK(resp)); e != nil {
			fmt.Fprintf(os.Stderr, "%v\n", e)
		}
	})

	demogo.Run(node)
}
EOF

